 final form=GlobalKey<FormState>(),title=TextEditingController(),body=TextEditingController();final keyValue=newKey();late String branch;Json? image;List<Json> services=[];String? serviceId;bool servicesLoading=true;int servicesGeneration=0;bool busy=false;Object? error;
