}
class PromotionDetail extends StatefulWidget{
 final ApiClient api;final String id;const PromotionDetail({super.key,required this.api,required this.id});
 @override State<PromotionDetail> createState()=>_PromotionDetailState();
}
class _PromotionDetailState extends State<PromotionDetail>{
 int revision=0;bool busy=false;Object? error;
 Future<void> act(Json r,String action)async{final accept=action=='ACCEPT';final confirmed=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(accept?'اعتماد تكلفة الإعلان':'سحب الإعلان'),content:Text(accept?'التكلفة المتفق عليها: ${money(r['feePiasters'])} ج.م\nالعرض من ${shortDate(r['startsAt'])} إلى ${shortDate(r['endsAt'])}.\nتُسجل مديونية عند الموافقة، وتستحق مع بداية الإعلان وتُخصم تلقائيًا من مستحقات الجيم المتاحة، والباقي من التحصيل القادم.':'الإعلان هيتشال من العرض لو كان منشورًا.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('رجوع')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('تأكيد'))]));if(confirmed!=true||!mounted)return;setState(()=>busy=true);try{await widget.api.request('promotions/requests/${widget.id}/action',method:'POST',body:{'action':action,'expectedVersion':r['version']});if(mounted)setState(()=>revision++);}catch(e){if(mounted)setState(()=>error=e);}finally{if(mounted)setState(()=>busy=false);}}
